create or replace function public.catalog_find_parts(search_query text,context_filter text default null,max_results integer default 31,after_number text default null,after_position text default null) returns table(position_id text,part_id text,number_normalized text,name text,assembly_id text,assembly_title text,context_id text,context_name text,reference text,required_quantity integer,conditions jsonb) language sql stable security invoker set search_path='' as $$ with term as materialized(select websearch_to_tsquery('simple',search_query) as query,regexp_replace(search_query,'[^0-9]','','g') as number where char_length(btrim(search_query)) between 2 and 200), matched as materialized(select p.id from public.parts p,term t where p.number_normalized=t.number or to_tsvector('simple',p.name||' '||coalesce(p.number_normalized,'')) @@ t.query union select pos.part_id from public.part_assembly_positions pos,term t where pos.active and (context_filter is null or pos.context_id=context_filter) and to_tsvector('simple',pos.source_name) @@ t.query) select x.id,p.id,p.number_normalized,x.source_name,a.id,a.title,c.id,c.name,x.reference,x.required_quantity,x.conditions from matched m join public.parts p on p.id=m.id join public.part_assembly_positions x on x.part_id=p.id join public.assemblies a on a.id=x.assembly_id join public.vehicle_catalog_contexts c on c.id=x.context_id where x.active and (context_filter is null or c.id=context_filter) and ((after_number is null and after_position is null) or (p.number_normalized,x.id)>(after_number,after_position)) order by p.number_normalized,x.id limit least(greatest(max_results,1),101); $$;
